INSERT INTO "articles" VALUES(1,'Sejarah Terbentuknya Danau Toba, Kisah Letusan Gunung Berapi Raksasa','sejarah-terbentuknya-danau-toba-kisah-letusan-gunung-berapi-raksasa',1,'Sejarah Terbentuknya Danau Toba, Kisah Letusan Gunung Berapi Raksasa
INSERT INTO "articles" VALUES(2,'Sejarah, Legenda, dan Rute di Danau Toba','sejarah-legenda-dan-rute-di-danau-toba',1,'Danau Toba adalah destinasi ikonik di Sumatera Utara yang terkenal nggak hanya di Indonesia tetapi juga di mancanegara. Sebagai danau vulkanik terbesar di Indonesia, Danau Toba memiliki panjang sekitar 100 kilometer, lebar 30 kilometer, dan kedalaman hingga 505 meter. 
INSERT INTO "articles" VALUES(3,'Danau Toba, Kawah Purba Terbesar di Dunia','danau-toba-kawah-purba-terbesar-di-dunia',3,'Pada megaerupsi 74.000 tahun lalu, gunung api purba Toba memuntahkan sebanyak 2.800 km kubik material vulkanik dan abunya menyebar hingga sejauh 9.000 km.
INSERT INTO "articles" VALUES(4,'Kawah Putih Tinggi Raja','kawah-putih-tinggi-raja',3,'Bicara soal wisata alam di Sumatra Utara tak ada habisnya. Di setiap kabupaten menawarkan pesona alam yang indah.
INSERT INTO "articles" VALUES(5,'Panorama Keindahan Bukit Sipolha','panorama-keindahan-bukit-sipolha',3,'Bukit Sipolha, yang terletak di Kabupaten Simalungun, Sumatera Utara, adalah destinasi wisata yang menawarkan keindahan alam yang memukau dengan pemandangan spektakuler Danau Toba.
INSERT INTO "articles" VALUES(6,'Wisata Sejarah: Rumah Pengasingan Bung Karno di Parapat','wisata-sejarah-rumah-pengasingan-bung-karno-di-parapat',3,'Kota Parapat merupakan salah satu tujuan pariwisata yang berada di Sumatera Utara. Kota di tepian Danau Toba ini menjadi saksi bisu sejarah bangsa Indonesia, karena di kota ini Presiden RI ke-1 Ir. Soekarno pernah diasingkan di pesanggrahan milik perkebunan Belanda.
