INSERT INTO "culinary_items" VALUES(1,'Dali ni Horbo','dali-ni-horbo','Makanan unik ini terdengar asing, namun pasti merasa pernah memakannya. Dali ni horbo merupakan makanan yang berbentuk seperti tahu dan terbuat dari susu kerbau alami.','Halal','Batak Toba / Samosir / Tapanuli',1,NULL,'2026-10-22 06:49:56');
INSERT INTO "culinary_items" VALUES(2,'Saksang','saksang','saksang adalah masakan khas suku Batak yang terbuat dari daging babi, daging anjing, atau daging kerbau yang dicincang kecil dan dibumbui dengan rempah-rempah, serta dimasak baik dengan menggunakan darah hasil sembelihan hewan tersebut (margota) atau olahan rempah biasa tanpa darah (na so margota).','Non-Halal (Daging Khas)','Batak Toba / Samosir / Tapanuli',1,NULL,'2026-10-22 06:49:56');
INSERT INTO "culinary_items" VALUES(3,'Naniarsik','naniarsik','Arsik adalah salah satu masakan khas masyarakat Batak atau yang disebut juga dengan dekke na niarsik, yang memiliki arti ikan yang dimasak hingga kering. Kata arsik berasal dari cara memasak hidangan ini, yaitu mangarsik yang berarti hidangan ikan disiram-siram atau diguyur selama proses memasak.
INSERT INTO "culinary_items" VALUES(4,'Babi Panggang Karo','babi-panggang-karo','Babi panggang karo (atau yang lebih populer dikenal dengan istilah BPK) adalah masakan yang terbuat dari daging babi yang dipanggang atau dibakar. Makanan ini adalah masakan khas Suku Karo, sehingga banyak ditemukan di berbagai kota yang banyak ditinggali oleh orang Karo seperti di Berastagi, Kabanjahe, dan Medan, bahkan di Pekanbaru, Serang, Tangerang, Jakarta, Bekasi, dan Bandung.
INSERT INTO "culinary_items" VALUES(5,'Manuk Napinadar','manuk-napinadar','Manuk napinadar atau ayam napinadar adalah masakan khas Batak yang biasanya dihidangkan pada pesta adat tertentu, biasanya disajikan saat seseorang sedang mengalami suka cita seperti kelahiran anak, pernikahan, dan saat seseorang akan berangkat merantau.
INSERT INTO "culinary_items" VALUES(6,'Dengke Mas na Niura','dengke-mas-na-niura','Dengke mas na niura adalah makanan tradisional khas Batak yang berasal dari tanah Batak, khususnya wilayah Toba, Pulau Samosir, Danau Toba, Tapanuli Utara, dan Humbang Hasundutan. Dahulu, masakan na niura dikhususkan untuk raja saja, tetapi semua orang-orang Batak saat ini dapat membuat dan menyantapnya karena rasanya yang enak. Masakan ini awalnya menggunakan ikan mujair, kemudian digunakan juga untuk ikan emas yang memang banyak ditemukan di Danau Toba.
INSERT INTO "culinary_items" VALUES(7,'Na Tinombur','na-tinombur','Na tinombur adalah makanan khas Batak, Sumatra Utara yang berbahan dasar ikan mas atau mujair. Hidangan ini biasanya disajikan dalam acara keluarga. Pengertian tombur sendiri adalah membasahi atau mengairi, sehingga hidangan ikan tersebut dilumuri dengan bumbu. Proses memasaknya diawali dengan membuat tombur atau bumbu dan sambal yang dilumuri ke ikan. Ikan mas atau mujair lantas dibakar atau digoreng terlebih dahulu. Rempah yang digunakan untuk bumbu ikan adalah andaliman, jahe, bawang merah, kemiri, dan jeruk nipis. Andaliman adalah bahan yang dapat menambah cita rasa yang lebih pedas dan gurih.','Halal','Batak Toba / Samosir / Tapanuli',1,NULL,'2026-10-22 06:49:56');
INSERT INTO "culinary_items" VALUES(8,'Mie Gomak','mie-gomak','Mi gomak adalah makanan yang terkenal sebagai masakan khas suku Batak Toba dari Sumatra Utara. Masakan ini adalah masakan khas daerah sekitar Danau Toba, mulai dari Porsea, Balige, Laguboti, Tarutung, hingga Tapanuli Selatan.  Mi ini juga dapat ditemukan di berbagai daerah di Sumatra Utara, mulai dari Medan, Siantar, Parapat, Labuhan Batu, Sibolga, hingga Deli Serdang. Namun, mi gomak sudah terkenal di berbagai provinsi dan juga beberapa masyarakat Indonesia yang berbeda provinsi.
INSERT INTO "culinary_items" VALUES(9,'Tanggo tanggo','tanggo-tanggo','masakan khas dari wilayah Batak Toba yang terbuat dari daging hewan, seperti babi atau anjing, dengan bumbu santan dan rempah-rempah (termasuk jeruk purut dan daun salam, ketumbar, bawang merah, bawang putih, cabai, merica, serai, jahe, lengkuas, kunyit, dan andaliman).[1] Masakan ini tidak jauh berbeda dengan sangsang, perbedaannya adalah daging yang akan dimasak menjadi tanggo tanggo dipotong lebih besar (sebesar kepalan tangan) dan dipadu dengan sayuran yang bukan saja dari daun singkong.','Non-Halal (Daging Khas)','Batak Toba / Samosir / Tapanuli',1,NULL,'2026-10-22 06:49:56');
INSERT INTO "culinary_items" VALUES(10,'Mie Sop','mie-sop','hidangan berkuah yang populer di Indonesia, terutama di Medan, Sumatera Utara. Secara harfiah, "mie sop" berarti mie dalam sup. Hidangan ini terdiri dari mie kuning atau bihun yang disajikan dalam kuah kaldu gurih, biasanya dari ayam, dengan berbagai tambahan seperti suwiran ayam, sayuran (seperti kol, daun bawang, seledri), dan terkadang telur rebus atau perkedel.','Halal','Batak Toba / Samosir / Tapanuli',1,NULL,'2026-10-22 06:49:56');
INSERT INTO "culinary_items" VALUES(11,'Sira Pege','sira-pege','Hidangan ini terbuat dari bahan sederhana seperti garam, jahe, bawang, cabai dan potongan ayam, yang menghasilkan rasa asin dan hangat dari jahe. Meskipun sederhana, hidangan ini menyimpan rasa khas yang erat dengan budaya Batak.
INSERT INTO "culinary_items" VALUES(12,'Sambal Tuktuk','sambal-tuktuk','Sambal tuktuk adalah sambal tradisional khas masyarakat Batak yang berasal dari Tapanuli, Sumatera Utara. Bahan-bahan untuk membuat sambal tuktuk tidak berbeda dengan bahan sambal-sambal, pembedanya dengan sambal yang lain adalah adanya andaliman.','Halal','Batak Toba / Samosir / Tapanuli',1,NULL,'2026-10-22 06:49:56');
