INSERT INTO "regencies" VALUES(1,'Kabupaten Toba','Toba','Balige','Pusat budaya Batak Toba, museum TB Silalahi, pantai pasir putih Lumban Bulbul, dan gerbang selatan Danau Toba.','2026-10-22 06:49:56');
INSERT INTO "regencies" VALUES(2,'Kabupaten Samosir','Samosir','Pangururan','Pulau vulkanik di tengah Danau Toba, kaya akan situs sejarah Batak, Tomok, Tuktuk, dan desa tenun Hutaraja.','2026-10-22 06:49:56');
INSERT INTO "regencies" VALUES(3,'Kabupaten Simalungun','Simalungun','Raya / Parapat','Gerbang utama wisata Parapat, kebun teh Sidamanik, Bukit Indah Simarjarunjung, dan panorama danau yang spektakuler.','2026-10-22 06:49:56');
INSERT INTO "regencies" VALUES(4,'Kabupaten Tapanuli Utara','Tapanuli Utara','Tarutung','Pintu masuk udara Bandara Internasional Silangit, Geosite Huta Ginjang, pemandian air soda Sipoholon, dan pacuan kuda tradisional.','2026-10-22 06:49:56');
INSERT INTO "regencies" VALUES(5,'Kabupaten Humbang Hasundutan','Humbang Hasundutan','Dolok Sanggul','Lembah Bakkara tempat kelahiran Raja Sisingamangaraja XII, Geosite Sipinsur dengan panorama pulau Sibandang, dan kopi arabika Lintong.','2026-10-22 06:49:56');
INSERT INTO "regencies" VALUES(6,'Kabupaten Dairi','Dairi','Sidikalang','Kawasan Tao Silalahi dengan garis pantai terpanjang dan danau terdalam, bukit perkemahan Paropo, dan kopi legendaris Sidikalang.','2026-10-22 06:49:56');
INSERT INTO "regencies" VALUES(7,'Kabupaten Karo','Karo','Kabanjahe','Gerbang utara kaldera Danau Toba, air terjun Sipiso-piso setinggi 120m, desa Tongging, dan agrowisata pegunungan Berastagi.','2026-10-22 06:49:56');
INSERT INTO "regencies" VALUES(8,'Kabupaten Pakpak Bharat','Pakpak Bharat','Salak','Wilayah penyangga ekosistem Danau Toba dengan hutan tropis, air terjun Lae Une, dan kebudayaan suku Batak Pakpak.','2026-10-22 06:49:56');
