INSERT INTO "reviews" VALUES(70,'destination',13,'papuma shop',NULL,5.0,'Tempatnya keren dan sejuk serta udara segar, cocok untuk keluarga sebab ada tempat bermain juga. Waktu berkunjung sebaiknya tidak waktu musim hujan dan datang sekitar jam 160 -170 WIB itu merupakan waktu berkunjung yang teaik. Waktu kita berkunjung ke tempat tersebut dan terjadi hujan, kalo dari jauh diluar wilayah tersebut untuk datang kedua kali harus butuh waktu lagi.','4 days ago');
