INSERT INTO "reviews" VALUES(85,'destination',15,'Janno Elveri Maun',NULL,5.0,'Air terjun yang langsung jatuh ke danau toba. Aliran airnya berasal dari Sungai Jangga (cmiiaw). Ornamen2 wisata yg sudah dibangun perlu peremajaan supaya lebih menarik, berwarna dan lebih mengundang wisatawan. Air terjun ini biasa dikunjungi menggunakan kapal wisata, kapasitas 40-60 penumpang. Speed boat, ataupun Jetski (biasanya disewa oleh pasangan2 muda, yang beulan madu atau ingin memangkas waktu perjalanan. Naik kapal wisata 100-120 menit waktu perjalanan. Jetsi atau Speed boat, bisa dipercepat sampai 30 menit. Pilih mana? Semua tersedia dari parapat. Yok berkunjung, supaya Air terjun ini lebih terkenal dan mendunia...','21 hours ago');
