INSERT INTO "reviews" VALUES(172,'destination',31,'The Compass Guy',NULL,4.0,'Lake Sidihoni is the kind of place that makes geography teachers giddy. Nestled on Samosir Island, which itself floats in the vast expanse of Lake Toba, Sidihoni earns its quirky nickname: “the lake above the lake.” It’s like nature’s own Russian nesting doll, but with more cows and fewer instructions.
INSERT INTO "reviews" VALUES(173,'destination',31,'rizky hermawan',NULL,4.0,'Danau di dalam area danau. Danau Sidihoni terletak di daerah Sidihoni yang berada di Pangururan masih berada di area di Pulau Samosir, Danau Toba, Kabupaten Samosir juga. Tidak besar tapi cukup asri dan bagus. Sering dijadikan sebagai tempat memancing masyarakat sekitar dan tentu saja sebagai tempat wisata.','2 months ago');
