INSERT INTO "reviews" VALUES(255,'destination',46,'Kristian Hutabarat',NULL,5.0,'Pantai Pulo Tao adalah destinasi wisata yang terletak di Pulau Samosir, Sumatera Utara. Pantai ini dikenal dengan suasana yang tenang dan pemandangan alam yang menawan. Pantai Pulo Tao menawarkan pasir putih yang bersih dan air Danau Toba yang jernih, cocok untuk berenang dan berjemur. Suasana di pantai ini relatif sepi, menjadikannya ideal untuk bersantai dan menikmati ketenangan. Selain itu, pemandangan di sekitar pantai yang dikelilingi oleh pegunungan dan vegetasi tropis menambah daya tariknya. Fasilitas di Pantai Pulo Tao mungkin sederhana, dengan beberapa warung lokal untuk makanan dan minuman. Akses ke pantai ini cukup mudah dari berbagai titik wisata di Samosir. Secara keseluruhan, Pantai Pulo Tao adalah pilihan yang baik untuk menikmati keindahan alam dan suasana damai di Samosir.','11 months ago');
