INSERT INTO "reviews" VALUES(358,'destination',66,'The Compass Guy',NULL,3.0,'Desa Wisata Tomok Parsaoran is like stepping into a Batak time capsule, but with souvenir stalls. It’s where ancient traditions meet modern bargaining skills, and where you can learn about centuries of culture right before haggling over fridge magnets shaped like buffalo horns.
INSERT INTO "reviews" VALUES(359,'destination',66,'awal udin',NULL,5.0,'Bernuasa magis tp lebih kepada histori.
INSERT INTO "reviews" VALUES(360,'destination',66,'Edwin Petrus',NULL,3.0,'Desa Wisata Tomok Parsaoran adalah sebuah objek wisata di Pulau Samosir yang lokasinya tidak terlalu jauh dari Pelabuhan Tomok. Di tempat ini, terdapat sejumlah toko yang menjual oleh-oleh mulai dari kain Batak, ornamen Batak, kerajinan tangan, kaos, pakaian, mainan, dan sebagainya. Untuk harga, pembeli perlu tawar menawar dengan penjual. Pembayaran hanya menggunakan uang tunai.
INSERT INTO "reviews" VALUES(361,'destination',66,'Suhardin Djalal',NULL,5.0,'Terdapat kegiatan kebudayaan Batak serta souvenir khas Samosir.','6 months ago');
