INSERT INTO "reviews" VALUES(382,'destination',70,'Fathir Alfath Din Harahap',NULL,5.0,'Huta sialagan yang terletak di desa Siallagan merupakan salah satu destinasi wisata yang menurutku wajib dikunjungi, disini kalian dapat melihat berbagai jenis rumah bolon ( rumah adat Batak Toba ) yang memiliki ciri dan keunikan yang khas , selain itu kita juga akan melihat adanya batu persidangan yang dimana merupakan tempat untuk membuat keputusan dan mengadili pelaku kejahatan pada saat itu .. yang terdiri atas bangku raja, penasehat, dukun, terdakwa dan pelaku kejahatan. Dan gak perlu khawatir, di tempat ini juga telah tersedia tour guide yang akan memandu seluruh wisatawan yang berkunjung untuk dapat memahami setiap elemen dan benda yang ada di tempat ini. Untuk fee ( uang masuk ) hanya 10 ribu rupiah saja. Terimakasih 😁','7 months ago');
