INSERT INTO "reviews" VALUES(390,'destination',71,'Septino Binsar',NULL,4.0,'Salah satu tempat bersejarah dan sakral. Suasana lingkungan asri, bersih dan udara sejuk. Banyak pohon rindang dan tempat duduk outdoor. Terdapat spot foto dengan view desa Sagala dan desa Limbong. HTM 5 ribu/orang, parkir 5 ribu/mobil. Saran diberikan papan informasi atau infografis tentang sejarah Sopo Guru, karena banyak juga pengunjung yang belum tahu sejarahnya.','3 months ago');
