INSERT INTO "reviews" VALUES(399,'destination',73,'Eka Mahessa',NULL,5.0,'Rekomendasi banget untuk mampir ke sini, budaya Batak terwakili disini walau tidak semuanya, tetapi cukup untuk membuka wawasan.
INSERT INTO "reviews" VALUES(400,'destination',73,'Merry Rut Patricia',NULL,4.0,'Museumnya kecil, koleksi juga tidak banyak, tapi menurut saya sangat menarik! Banyak benda2 terkait kebudayaan batak kuno yg baru pertama kali saya lihat. Di sana ada rumah-rumah tradisional juga dan semacam rumah vintage (gaya kolonial). Tiket masuk 20rb.','6 months ago');
INSERT INTO "reviews" VALUES(401,'destination',73,'Ramlan depary sumatra',NULL,3.0,'Masih selesai renovasi','8 months ago');
INSERT INTO "reviews" VALUES(402,'destination',73,'Edwin van der Hoek',NULL,4.0,'The museum is under renovation right now. There will be a new boathouse also in the future. The small village is accessible but deserted. It''s too bad that there are no traditional dances any more or people in traditional clothes explaining the history of the place. But still an impressive place to visit if you like Batak-culture.','8 months ago');
INSERT INTO "reviews" VALUES(403,'destination',74,'po. aritonang',NULL,5.0,'Tugu Aritonang👍👍 Oppungsunggu, Rajagukguk dan Simaremare👍👍 …','3 months ago');
INSERT INTO "reviews" VALUES(404,'destination',74,'Exaudio Siregar',NULL,5.0,'Tugu persatuan Marga Aritonang (Ompusunggu, Rajagukguk, dan Simare-mare). Letaknya berada di atas bukit yang sangat indah. Bisa melihat luasnya hamparan Danau Toba dan desa Buntu Raja yang berkelok-kelok tepat di bawah Hutaginjang.','Edited 10 months ago');
INSERT INTO "reviews" VALUES(405,'destination',74,'Alex Juntak',NULL,5.0,'Tugu Aritonang, tempatnya sejuk dan nyaman, cocok buat nyantai sambil Mandang ke danau Toba ...
INSERT INTO "reviews" VALUES(406,'destination',74,'Putri Opusunggu',NULL,5.0,'Feb 2019 pas ulang tahun bapakku ke 77, sekeluarga kami kesini krna udh tua jd gak bisa naik sampe keatas dan dikunci, aku lompat masuk k dlm mau pegang tugunya (kemarok dikit)😂 trus juli 2019 sblum meninggal bapak ku pengen ksni lgi mau naik sampe atas biar bs pegang tugu katanya, tp krna udh gak bs jalan bahkan cuma bs tidur jdi gk tercapai. trus 2022 GMTA medan buat event nasional kemah wisata dan festival budaya, aku salah 1 panitianya 1minggu full bebas foto di tugu Aritonang 🥰','a year ago');
