INSERT INTO "reviews" VALUES(410,'destination',74,'JC Faulina',NULL,4.0,'Senang sekali bisa berada di tempat ini. Sambil memandang hamparan Danau Toba dari tempat ini sangat memanjakan mata dan tugu terawat dengan baik 🥰. Mungkin ada yg berdoa dengan membawa anggir dan telor karna ada beberapa di situ pas ke tugu ini 🤭😊.','a year ago');
