INSERT INTO "reviews" VALUES(412,'destination',75,'Lia',NULL,4.0,'Tempatnya bukan pemandian ya sebenarnya lebih ke membasuh diri. 1 bilik 4 Mata air, 1 bilik lagi 3 Mata air. Tempat sakral jadi ga boleh pakai kasut, ulos boleh dipakai Dan akan disandangkan sesuai adat setempat. Ada aturannya. Tempatnya rada berlumut jadi mau hati hati melangkah. Di samping, pemandangan sawah bagus banget','a month ago');
INSERT INTO "reviews" VALUES(413,'destination',75,'Nancy Darmarose Sinaga',NULL,2.0,'Dibagi 2 pemandiannya, 4 mata air dulu lalu 3 mata air di sebelah nya. Ada guide yang menjelaskan sejarah aek sipitu dai ini. Apes banget waktu mau masuk ke pemandian 3 mata air sedang ada anak-anak mandi lengkap dengan sabun nya.','3 months ago');
