INSERT INTO "services" VALUES(39,'Kano','kano',6,1,'Kelompok Pengelola Kano','adventure','Permainan kano adalah aktivitas rekreasi atau olahraga air yang menggunakan perahu kecil ringan bernama kano, yang digerakkan dengan dayung.
