INSERT INTO "services" VALUES(41,'Flyboard di Parapat','flyboard-di-parapat',6,3,'Kelompok Pengelola Flyboard di Parapat','adventure','Flyboard adalah wahana air terbaru yang tersedia di Danau Toba, memungkinkan pengguna untuk melayang di atas air dengan bantuan jet air bertekanan tinggi. Wahana ini merupakan atraksi yang sedang populer di kalangan wisatawan',50000,250000,'per orang / paket','Rp 50.000 - Rp 250.000','Pemandu lokal, alat keselamatan/perlengkapan, spot foto','Parapat, Kabupaten Simalungun',NULL,NULL,'0812-7888-9900','6281278889900',4.8,0,1,1,'active',NULL,'2026-10-22 06:49:56');
