INSERT INTO "services" VALUES(47,'Paralayang Huta Ginjang','paralayang-huta-ginjang',6,4,'Kelompok Pengelola Paralayang Huta Ginjang','adventure','Puncak Huta Ginjang di Kecamatan Muara, Tapanuli Utara, Sumut, adalah surga paralayang di Sumatera.
