INSERT INTO "services" VALUES(50,'Kampung Ulos Hutaraja','kampung-ulos-hutaraja',6,2,'Kelompok Pengelola Kampung Ulos Hutaraja','cultural_experience','Wisatawan bisa bereksplorasi lebih dalam mengenai kain ulos di Kampung Ulos Huta Raja mulai dari proses produksi kain hingga suasana kampung Ulos yang kental khas budaya Batak. Kampung ini bahkan dianggap sebagai salah satu desa wisata terbaik di wilayah Destinasi Pariwisata Super Prioritas (DSP) Danau Toba.
