INSERT INTO "services" VALUES(52,'Trekking Guide Geosite Huta Ginjang & Pemandangan Kaldera','trekking-guide-geosite-huta-ginjang-pemandangan-kaldera',5,4,'Erick Hutabarat (Pemuda Sadar Wisata Muara)','tour_guide','Pemanduan jalur trekking perbukitan pinus Huta Ginjang dengan pemandangan 360 derajat Danau Toba dan Pulau Sibandang, serta edukasi fenomena supervolcano.',100000,200000,'per trip','Rp 100.000 - Rp 200.000 / trip','Pemandu lokal berpengalaman, briefing budaya, alat bantu','Huta Ginjang, Kec. Muara, Tapanuli Utara',NULL,NULL,'0813-9088-7766','6281390887766',4.8,0,1,1,'active',NULL,'2026-10-22 06:49:56');
INSERT INTO "services" VALUES(53,'Live Workshop Belajar Menenun Ulos Tradisional','live-workshop-belajar-menenun-ulos-tradisional',6,2,'Inang Martalina Simarmata (Penenun Hutaraja)','cultural_experience','Praktik langsung teknik menenun ulos Batak dengan alat tenun tradisional (gedokan), memahami makna motif ragi hotang, mangiring, dan sibolang.',75000,150000,'per orang (termasuk bahan)','Rp 75.000 - Rp 150.000 / orang','Pemandu lokal berpengalaman, briefing budaya, alat bantu','Kampung Ulos Hutaraja, Desa Lumban Suhi-suhi Toruan, Samosir',NULL,NULL,'0852-6111-2244','6285261112244',5.0,1,1,1,'active',NULL,'2026-10-22 06:49:56');
INSERT INTO "services" VALUES(54,'Sewa Perahu Tradisional Solu Bolon Keliling Pantai Lumban Bulbul','sewa-perahu-tradisional-solu-bolon-keliling-pantai-lumban-bulbul',6,1,'Nelayan Tradisional Lumban Bulbul','boat_rental','Menikmati tenangnya air danau dengan perahu tradisional dayung kayu (solu) ditemani nelayan lokal sambil menyaksikan matahari terbit (sunrise).',50000,100000,'per jam (kapasitas 4 orang)','Rp 50.000 - Rp 100.000 / jam','Pemandu lokal berpengalaman, briefing budaya, alat bantu','Pantai Lumban Bulbul, Balige, Kabupaten Toba',NULL,NULL,'0812-3344-5566','6281233445566',4.7,0,1,1,'active',NULL,'2026-10-22 06:49:56');
